#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Assemble inactive author shapes and exact full-case references; no approval rows."""
from pathlib import Path
import hashlib, json, re, shutil
from datetime import datetime, timezone
ROOT=Path(__file__).resolve().parent
REPO=next(p for p in ROOT.parents if (p/'app/scripts/positiveGoalEvidenceProfileModel.ts').exists())
SOURCE=ROOT.parent/'chemie-acid-base-seven-existing-whole-goals-fourteen-material-cases-author-20261014-v1'
def digest(b): return 'sha256:'+hashlib.sha256(b).hexdigest()
def dump(path,x): path.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def binding(path):
 b=path.read_bytes(); return {'path':str(path.relative_to(REPO)),'sha256':digest(b),'bytes':len(b)}
sources=[
 (SOURCE/'inputs/whole-seven-current-goals.exact.json','whole-seven-current-goals.exact.json'),
 (SOURCE/'materials.fourteen-complete-cases.de-en.author.md','fourteen-complete-cases.de-en.exact.author.md'),
 (SOURCE/'NEUTRAL.exact-seven-whole-goals-and-fourteen-cases.author-inputs.json','source-neutral-author-inputs.exact.json'),
 (REPO/'app/scripts/positiveGoalEvidenceProfileModel.ts','positiveGoalEvidenceProfileModel.exact.ts'),
 (REPO/'app/scripts/positiveGoalEvidenceReview.ts','positiveGoalEvidenceReview.exact.ts'),
 (REPO/'contracts/goal-evidence/v2/goal-evidence-profile.schema.json','goal-evidence-profile.schema.exact.json'),
 (REPO/'curricula/DE/Gymnasium/quality/goal-evidence/prompts/chemistry-positive-understanding-evidence-profile-criteria-v1.md','chemistry-positive-understanding-evidence-profile-criteria-v1.exact.md'),
]
provenance=[]
for p,name in sources:
 q=ROOT/'inputs'/name; shutil.copyfile(p,q)
 provenance.append({'source':binding(p),'exactLocalCopy':binding(q)})
goals=json.loads((ROOT/'inputs/whole-seven-current-goals.exact.json').read_text())
material=(ROOT/'inputs/fourteen-complete-cases.de-en.exact.author.md').read_text()
starts=list(re.finditer(r'^### (G[1-7]-C[12]) — (.+)$',material,re.M))
cases=[]
for j,m in enumerate(starts):
 end=starts[j+1].start() if j+1<len(starts) else len(material)
 block=material[m.start():end]
 # A following goal heading belongs to the next goal, not this full case.
 nextgoal=re.search(r'^## G[1-7] — ',block,re.M)
 if nextgoal: block=block[:nextgoal.start()]
 cases.append({'id':m[1],'title':m[2],'sourceHeading':m[0], 'fullCaseText':block,'fullCaseTextSha256':digest(block.encode()),'sourcePath':'inputs/fourteen-complete-cases.de-en.exact.author.md','sourceStartLine':material[:m.start()].count('\n')+1})
dump(ROOT/'inputs/fourteen-full-cases.bound.exact.json',{'schemaVersion':1,'role':'exact full-case extracts; author material only','sourceMaterial':binding(ROOT/'inputs/fourteen-complete-cases.de-en.exact.author.md'),'cases':cases})

def expectation(i,de,en,pde,pen): return {'id':i,'essentialUnderstandingDe':de,'essentialUnderstandingEn':en,'observablePerformanceDe':pde,'observablePerformanceEn':pen}
def axis(i,de,en): return {'id':i,'textDe':de,'textEn':en}
def brief(g,c,de,en,ede,een,fde,fen):
 ref=f'inputs/fourteen-full-cases.bound.exact.json, Fall G{g}-C{c}'
 return {'id':f'g{g}-c{c}','taskDemandDe':de+' Vollständiges Material, Auftrag, Lösung und vier Kriterien: '+ref+'.','taskDemandEn':en+' Complete material, task, solution and four criteria: '+ref.replace('Fall ','case ')+'.','expectedPerformanceDe':ede,'expectedPerformanceEn':een,'understandingFocusDe':fde,'understandingFocusEn':fen}
